const ART_IDS=['shin','rento','reika','souta','shiori','aoi','hayato','yuuki','takumi','miho','daisuke','nanami','kazuma','rin','ren','karen','patissier'];
function portrait(id,face=0,classes=''){return `<span class="sprite ${classes}" aria-hidden="true" style="background-image:url('assets/characters/${ART_IDS[id]}-atlas.png');background-position:${face%3*50}% ${Math.floor(face/3)*100}%"></span>`;}
function backdrop(scene,video=true){const image=scene==='pantry'?'pantry-v2':scene;return `<div class="backdrop"><img src="assets/backgrounds/${image}.png" alt=""/>${video&&['exterior','hall','pantry'].includes(scene)?`<video muted autoplay loop playsinline preload="metadata" poster="assets/backgrounds/${image}.png" aria-hidden="true"><source src="assets/video/${scene}-loop.webm" type="video/webm"></video>`:''}</div>`;}
const ITEM_LOOKUP={key:[0,2],metal:[0,4],structure:[1,3],foot:[1,1],time:[1,1],photo:[1,0],roster:[1,8],staff:[0,11],ink:[0,5],marker:[0,6],miho:[1,5],fork:[0,7],soup:[0,7],burnt:[0,9],full:[1,10],recipe:[1,2],jars:[0,10],smell:[0,0],ingredient:[0,10],pride:[1,2],reject:[1,10],sensor:[1,9],lift:[1,9],conceal:[0,5]};
function itemArt(e){const v=ITEM_LOOKUP[e]||[1,1];return `<span class="item-art" aria-hidden="true" style="background-image:url('assets/items/${v[0]?'records':'props'}-atlas.png');background-position:${v[1]%4/3*100}% ${Math.floor(v[1]/4)*50}%"></span>`;}
const Sounds={enabled:false,bgm:null,track:'',volume:.25,play(name,loop=false){if(!this.enabled)return;if(loop){if(name===this.track&&this.bgm)return;this.bgm?.pause();this.track=name;this.bgm=new Audio('assets/audio/'+name+'.wav');this.bgm.loop=true;this.bgm.volume=this.volume;this.bgm.play().catch(()=>{});}else{const fx=new Audio('assets/audio/'+name+'.wav');fx.volume=.28;fx.play().catch(()=>{});}},toggle(){this.enabled=!this.enabled;if(!this.enabled){this.bgm?.pause();this.track='';}else this.play(view==='cover'?'bgm-title':view==='result'?'bgm-ending':'bgm-investigation',true);document.querySelector('#sound-toggle').textContent=this.enabled?'音：ON':'音：OFF';}};
